#ifndef SOFDEC_MPVMC_PPC_H
#define SOFDEC_MPVMC_PPC_H

#include "types.h"

/* CRI Sofdec MPEG motion compensation, 8x8 chroma block copy with no interpolation: the PowerPC
 * kernels of MPVMC08_OneRef1p (movie_module fn_12_DC78), one per source alignment.
 *
 * Retail's kernel bodies are inline assembly on register variables, not C:
 *  - lwzux and lfdux (load with update, indexed) are never generated by MWCC from C; no
 *    instruction-selection or peephole path emits them, only the inline assembler;
 *  - the 2/6 kernel builds its second word with slwi + or where MWCC's C code generator emits rlwimi;
 *  - the fourth prefetch of the 3/7 kernel uses a different index from its neighbours.
 * The compiler still allocates the registers and schedules the instructions, so each kernel names its
 * operands as register variables, declared in the order that gives retail's registers.
 *
 * They are macros, expanded inside the caller, rather than static inline functions: an inline function's
 * parameter copies change MWCC's register numbering (245 register rows differ). `context` is the
 * MPVMCContext pointer and `s` the caller's register variable holding context->reference0; the 1/5 and
 * 3/7 kernels step `s` in place. A macro is one logical line, hence the ';' after each instruction. */

/* Source 8-byte aligned: eight rows moved as doubles. */
#define MPVMC08_COPY_AL0(context, s) \
    register s32 stride; \
    register const u8 *p; \
    register u32 *d; \
    register f64 x0; \
    register f64 x1; \
    register f64 x2; \
    register f64 x3; \
    register f64 x4; \
    register f64 x5; \
    register f64 x6; \
    register f64 x7; \
    stride = context->reference_stride; \
    p = s; \
    d = (u32 *)context->destination; \
    asm { \
        lfd x0, 0(s); \
        lfdux x1, p, stride; \
        lfdux x2, p, stride; \
        lfdux x3, p, stride; \
        lfdux x4, p, stride; \
        lfdux x5, p, stride; \
        lfdux x6, p, stride; \
        lfdux x7, p, stride; \
        stfd x0, 0(d); \
        stfd x1, 8(d); \
        stfd x2, 16(d); \
        stfd x3, 24(d); \
        stfd x4, 32(d); \
        stfd x5, 40(d); \
        stfd x6, 48(d); \
        stfd x7, 56(d); \
    }

/* Source 4-byte aligned: eight rows moved as word pairs, each row loaded before the previous one is stored. */
#define MPVMC08_COPY_AL4(context, s) \
    register s32 stride; \
    register u32 *d; \
    register const u8 *p; \
    register u32 a0; \
    register u32 a1; \
    register u32 b0; \
    register u32 b1; \
    stride = context->reference_stride; \
    p = s; \
    d = (u32 *)context->destination; \
    asm { \
        lwz a0, 0(s); \
        lwz a1, 4(s); \
        lwzux b0, p, stride; \
        lwz b1, 4(p); \
        stw a0, 0(d); \
        stw a1, 4(d); \
        lwzux a0, p, stride; \
        lwz a1, 4(p); \
        stw b0, 8(d); \
        stw b1, 12(d); \
        lwzux b0, p, stride; \
        lwz b1, 4(p); \
        stw a0, 16(d); \
        stw a1, 20(d); \
        lwzux a0, p, stride; \
        lwz a1, 4(p); \
        stw b0, 24(d); \
        stw b1, 28(d); \
        lwzux b0, p, stride; \
        lwz b1, 4(p); \
        stw a0, 32(d); \
        stw a1, 36(d); \
        lwzux a0, p, stride; \
        lwz a1, 4(p); \
        stw b0, 40(d); \
        stw b1, 44(d); \
        lwzux b0, p, stride; \
        lwz b1, 4(p); \
        stw a0, 48(d); \
        stw a1, 52(d); \
        stw b0, 56(d); \
        stw b1, 60(d); \
    }

/* Source at 2 or 6 mod 8: a halfword, a word and a halfword per row, re-packed into two words; two passes of four rows. */
#define MPVMC08_COPY_AL2(context, s) \
    register s32 stride; \
    register s32 pitch; \
    register u32 *d; \
    register const u8 *q; \
    register u32 t; \
    register u32 h0; \
    register u32 w; \
    register u32 h1; \
    s32 i; \
    stride = context->reference_stride; \
    q = s; \
    d = (u32 *)context->destination; \
    pitch = stride & ~1; \
    for (i = 0; i < 2; i++) { \
        asm { \
            lhz h0, 0(q); \
            lwz w, 2(q); \
            lhz h1, 6(q); \
            slwi h0, h0, 16; \
            rlwimi h0, w, 16, 16, 31; \
            slwi t, w, 16; \
            or h1, t, h1; \
            stw h0, 0(d); \
            stw h1, 4(d); \
            add q, q, pitch; \
            lwz w, 2(q); \
            lhz h0, 0(q); \
            lhz h1, 6(q); \
            slwi t, w, 16; \
            slwi h0, h0, 16; \
            rlwimi h0, w, 16, 16, 31; \
            or h1, t, h1; \
            stw h0, 8(d); \
            stw h1, 12(d); \
            add q, q, pitch; \
            lwz w, 2(q); \
            lhz h0, 0(q); \
            lhz h1, 6(q); \
            slwi t, w, 16; \
            slwi h0, h0, 16; \
            rlwimi h0, w, 16, 16, 31; \
            or h1, t, h1; \
            stw h0, 16(d); \
            stw h1, 20(d); \
            add q, q, pitch; \
            lwz w, 2(q); \
            lhz h0, 0(q); \
            lhz h1, 6(q); \
            slwi t, w, 16; \
            slwi h0, h0, 16; \
            rlwimi h0, w, 16, 16, 31; \
            or h1, t, h1; \
            stw h0, 24(d); \
            stw h1, 28(d); \
            add q, q, pitch; \
            addi d, d, 32; \
        } \
    }

/* Source at 1 or 5 mod 8: rows read from s - 1 and shifted left one byte across two words and a trailing byte. */
#define MPVMC08_COPY_AL1(context, s) \
    register s32 stride; \
    register s32 stride2; \
    register u32 *d; \
    register u32 a0; \
    register u32 w1; \
    register u32 a2; \
    register u32 b0; \
    register u32 b2; \
    stride = context->reference_stride; \
    s -= 1; \
    d = (u32 *)context->destination; \
    stride2 = stride * 2; \
    asm { \
        dcbt s, stride; \
        lwz a0, 0(s); \
        lwz w1, 4(s); \
        lbz a2, 8(s); \
        dcbt s, stride2; \
        slwi a0, a0, 8; \
        rlwimi a0, w1, 8, 24, 31; \
        rlwimi a2, w1, 8, 0, 23; \
        lwzux b0, s, stride; \
        lwz w1, 4(s); \
        lbz b2, 8(s); \
        stw a0, 0(d); \
        stw a2, 4(d); \
        dcbt s, stride2; \
        slwi b0, b0, 8; \
        rlwimi b0, w1, 8, 24, 31; \
        rlwimi b2, w1, 8, 0, 23; \
        lwzux a0, s, stride; \
        lwz w1, 4(s); \
        lbz a2, 8(s); \
        stw b0, 8(d); \
        stw b2, 12(d); \
        dcbt s, stride2; \
        slwi a0, a0, 8; \
        rlwimi a0, w1, 8, 24, 31; \
        rlwimi a2, w1, 8, 0, 23; \
        lwzux b0, s, stride; \
        lwz w1, 4(s); \
        lbz b2, 8(s); \
        stw a0, 16(d); \
        stw a2, 20(d); \
        dcbt s, stride2; \
        slwi b0, b0, 8; \
        rlwimi b0, w1, 8, 24, 31; \
        rlwimi b2, w1, 8, 0, 23; \
        lwzux a0, s, stride; \
        lwz w1, 4(s); \
        lbz a2, 8(s); \
        stw b0, 24(d); \
        stw b2, 28(d); \
        dcbt s, stride2; \
        slwi a0, a0, 8; \
        rlwimi a0, w1, 8, 24, 31; \
        rlwimi a2, w1, 8, 0, 23; \
        lwzux b0, s, stride; \
        lwz w1, 4(s); \
        lbz b2, 8(s); \
        stw a0, 32(d); \
        stw a2, 36(d); \
        dcbt s, stride2; \
        slwi b0, b0, 8; \
        rlwimi b0, w1, 8, 24, 31; \
        rlwimi b2, w1, 8, 0, 23; \
        lwzux a0, s, stride; \
        lwz w1, 4(s); \
        lbz a2, 8(s); \
        stw b0, 40(d); \
        stw b2, 44(d); \
        slwi a0, a0, 8; \
        rlwimi a0, w1, 8, 24, 31; \
        rlwimi a2, w1, 8, 0, 23; \
        lwzux b0, s, stride; \
        lwz w1, 4(s); \
        lbz b2, 8(s); \
        stw a0, 48(d); \
        stw a2, 52(d); \
        slwi b0, b0, 8; \
        rlwimi b0, w1, 8, 24, 31; \
        rlwimi b2, w1, 8, 0, 23; \
        stw b0, 56(d); \
        stw b2, 60(d); \
    }

/* Source at 3 or 7 mod 8: rows read from s - 3 and shifted left three bytes across three words.
 * The fourth prefetch uses stride, not stride * 2, as retail does. */
#define MPVMC08_COPY_AL3(context, s) \
    register s32 stride; \
    register s32 stride2; \
    register u32 *d; \
    register u32 a0; \
    register u32 a1; \
    register u32 a2; \
    register u32 b0; \
    register u32 b1; \
    register u32 b2; \
    stride = context->reference_stride; \
    s -= 3; \
    d = (u32 *)context->destination; \
    stride2 = stride * 2; \
    asm { \
        dcbt s, stride; \
        lwz a0, 0(s); \
        lwz a1, 4(s); \
        lwz a2, 8(s); \
        dcbt s, stride2; \
        slwi a0, a0, 24; \
        rlwimi a0, a1, 24, 8, 31; \
        srwi a2, a2, 8; \
        rlwimi a2, a1, 24, 0, 7; \
        lwzux b0, s, stride; \
        lwz b1, 4(s); \
        lwz b2, 8(s); \
        stw a0, 0(d); \
        stw a2, 4(d); \
        dcbt s, stride2; \
        slwi b0, b0, 24; \
        rlwimi b0, b1, 24, 8, 31; \
        srwi b2, b2, 8; \
        rlwimi b2, b1, 24, 0, 7; \
        lwzux a0, s, stride; \
        lwz a1, 4(s); \
        lwz a2, 8(s); \
        stw b0, 8(d); \
        stw b2, 12(d); \
        dcbt s, stride2; \
        slwi a0, a0, 24; \
        rlwimi a0, a1, 24, 8, 31; \
        srwi a2, a2, 8; \
        rlwimi a2, a1, 24, 0, 7; \
        lwzux b0, s, stride; \
        lwz b1, 4(s); \
        lwz b2, 8(s); \
        stw a0, 16(d); \
        stw a2, 20(d); \
        dcbt s, stride; \
        slwi b0, b0, 24; \
        rlwimi b0, b1, 24, 8, 31; \
        srwi b2, b2, 8; \
        rlwimi b2, b1, 24, 0, 7; \
        lwzux a0, s, stride; \
        lwz a1, 4(s); \
        lwz a2, 8(s); \
        stw b0, 24(d); \
        stw b2, 28(d); \
        dcbt s, stride2; \
        slwi a0, a0, 24; \
        rlwimi a0, a1, 24, 8, 31; \
        srwi a2, a2, 8; \
        rlwimi a2, a1, 24, 0, 7; \
        lwzux b0, s, stride; \
        lwz b1, 4(s); \
        lwz b2, 8(s); \
        stw a0, 32(d); \
        stw a2, 36(d); \
        dcbt s, stride2; \
        slwi b0, b0, 24; \
        rlwimi b0, b1, 24, 8, 31; \
        srwi b2, b2, 8; \
        rlwimi b2, b1, 24, 0, 7; \
        lwzux a0, s, stride; \
        lwz a1, 4(s); \
        lwz a2, 8(s); \
        stw b0, 40(d); \
        stw b2, 44(d); \
        slwi a0, a0, 24; \
        rlwimi a0, a1, 24, 8, 31; \
        srwi a2, a2, 8; \
        rlwimi a2, a1, 24, 0, 7; \
        lwzux b0, s, stride; \
        lwz b1, 4(s); \
        lwz b2, 8(s); \
        stw a0, 48(d); \
        stw a2, 52(d); \
        slwi b0, b0, 24; \
        rlwimi b0, b1, 24, 8, 31; \
        srwi b2, b2, 8; \
        rlwimi b2, b1, 24, 0, 7; \
        stw b0, 56(d); \
        stw b2, 60(d); \
    }

#endif
